import { Component, Prop, Vue } from 'vue-property-decorator';
import { SettingsEventEmitter } from '../../../event-emitter';
import { OPTIONS } from '../../../options';
import { SubMenuManager } from '../../../sub-settings-manager';
import { IOpenSubMenuOptions, ISubSettingMenu } from '../../../types';
import SvgIcon from '../../common/svg-icon/index.vue';
import SettingsMenuSubMenu from '../sub-menu/index.vue';

@Component({
    name: 'SettingsMenuRoot',
    components: {
        SettingsMenuSubMenu,
        SvgIcon
    }
})
export default class SettingsMenuRoot extends Vue {
    @Prop({
        type: String,
        required: true
    })
    public buildVersion: string;

    public isVisible: boolean = false;

    public isAnimating: boolean = false;

    public activeSubMenu: ISubSettingMenu | null = null;

    public themeColour: string = OPTIONS.theme.midAccent.string;

    public subMenuLabel: string = '';

    public subMenuProps: { [key: string]: unknown } = {};

    public mounted() {
        this.onShow = this.onShow.bind(this);
        this.onHide = this.onHide.bind(this);
        this.onToggle = this.onToggle.bind(this);

        SettingsEventEmitter.on('show', this.onShow);
        SettingsEventEmitter.on('hide', this.onHide);
        SettingsEventEmitter.on('toggle', this.onToggle);
        SettingsEventEmitter.on('inGameShow', this.onInGameShow);
        SubMenuManager.on('open', this.onShowSubMenu);
        SubMenuManager.on('close', this.onCloseSubMenu);
    }

    public destroy() {
        SettingsEventEmitter.off('show', this.onShow);
        SettingsEventEmitter.off('hide', this.onHide);
        SettingsEventEmitter.off('toggle', this.onToggle);
        SettingsEventEmitter.off('inGameShow', this.onInGameShow);
        SubMenuManager.off('open', this.onShowSubMenu);
        SubMenuManager.off('close', this.onCloseSubMenu);
    }

    public onShow() {
        if (this.isAnimating || this.isVisible) return;

        this.isAnimating = true;
        this.isVisible = true;
    }

    public onTransitionEnd(event: TransitionEvent) {
        if (event.propertyName === 'transform') {
            this.isAnimating = false;
        }
    }

    public onHide() {
        this.isVisible = false;
        SubMenuManager.close();
    }

    public onToggle() {
        this.isVisible = !this.isVisible;

        if (!this.isVisible) {
            SubMenuManager.close();
        }
    }

    public onClose() {
        SettingsEventEmitter.emit('hide');
    }

    public onShowSubMenu(options: IOpenSubMenuOptions) {
        this.onCloseSubMenu();
        this.activeSubMenu = SubMenuManager.get(options.id);
        this.subMenuLabel = options.label || this.activeSubMenu.label;
        this.subMenuProps = options.props ?? this.activeSubMenu.props ?? {};
    }

    public async onInGameShow(options: IOpenSubMenuOptions) {
        this.onShow();
    
        // Wait until isAnimating becomes false
        await new Promise<void>((resolve) => {
            const interval = setInterval(() => {
                if (!this.isAnimating) {
                    clearInterval(interval);
                    resolve();
                }
            }, 50);
        });

        SubMenuManager.open({ id: options.id });
    }

    public onCloseSubMenu() {
        this.activeSubMenu = null;
    }
}
